<?php require 'config/db.php';require 'includes/auth.php';require_role(['ADMIN','OPERATOR']);$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM incidents WHERE id=?');$s->execute([$id]);$r=$s->fetch();if(!$r)exit('Incident not found.');if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare('UPDATE incidents SET incident_type=?,description=?,location=?,severity=?,status=? WHERE id=?');$s->execute([trim($_POST['incident_type']),trim($_POST['description']),trim($_POST['location']),$_POST['severity'],$_POST['status'],$id]);audit($pdo,'Incident updated','Incident #'.$id);$_SESSION['flash']='Incident updated.';header('Location: incidents.php');exit;}$page_title='Edit Incident';require 'includes/header.php';?><section class="panel"><form class="form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input name="incident_type" value="<?=e($r['incident_type'])?>" required><input name="location" value="<?=e($r['location'])?>" required><select name="severity"><?php foreach(['Low','Medium','High','Critical'] as $x):?><option <?=$r['severity']===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select><select name="status"><?php foreach(['Open','Investigating','Resolved'] as $x):?><option <?=$r['status']===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select><textarea name="description" class="full"><?=e($r['description'])?></textarea><button>Update Incident</button><a class="btn secondary" href="incidents.php">Cancel</a></form></section><?php require 'includes/footer.php';?>
